"/**
 * Empirical Verification of Proposed M2 Modernization Changes
 */

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// 1. Audit DOM sinks in proposed files
console.log('--- Step 1: Auditing DOM sinks in proposed files ---');
const homeCode = fs.readFileSync('.agents/teamwork/explorer_ui_m2_1/proposed_home.js', 'utf8');
const catalogCode = fs.readFileSync('.agents/teamwork/explorer_ui_m2_1/proposed_catalog.js', 'utf8');

assert(!/\.innerHTML\s*=/.test(homeCode), 'Zero .innerHTML = in proposed_home.js');
assert(!/\.outerHTML\s*=/.test(homeCode), 'Zero .outerHTML = in proposed_home.js');
assert(!/document\.write\(/.test(homeCode), 'Zero document.write in proposed_home.js');
assert(!/window\.eval\(/.test(homeCode), 'Zero eval in proposed_home.js');
console.log('  ✔ proposed_home.js has STRICT ZERO DOM SINKS!');

assert(!/\.innerHTML\s*=/.test(catalogCode), 'Zero .innerHTML = in proposed_catalog.js');
assert(!/\.outerHTML\s*=/.test(catalogCode), 'Zero .outerHTML = in proposed_catalog.js');
assert(!/document\.write\(/.test(catalogCode), 'Zero document.write in proposed_catalog.js');
assert(!/window\.eval\(/.test(catalogCode), 'Zero eval in proposed_catalog.js');
console.log('  ✔ proposed_catalog.js has STRICT ZERO DOM SINKS!');

// 2. Audit components.css tokens & requirements
console.log('\n--- Step 2: Auditing components.css requirements ---');
const css = fs.readFileSync('.agents/teamwork/explorer_ui_m2_1/proposed_components.css', 'utf8');

assert.match(css, /\.hero-banner[\s\S]*?height:\s*var\(--hero-banner-height\)/, 'Hero banner retains var(--hero-banner-height)');
assert.match(css, /\.hero-backdrop-img[\s\S]*?transition:\s*opacity 0\.9s/, 'Hero backdrop img has 0.9s transition');
assert.match(css, /\.hero-gradient-overlay[\s\S]*?rgba\(14,\s*16,\s*20,\s*0\.96\)/, 'Hero gradient overlay matches Google TV cinema palette');
assert.match(css, /\.split-action-group/, 'Split action group exists');

